fn blacksmith_miner_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_amount = Val::from(0);
    let mut l_cost = Val::from(0);
    let mut l_weight = Val::from(0);
    if ctx.call(Function::CheckWeight, vec![Val::from(1201), Val::from(1)])? == 0 {
        ctx.mes("^3355FFWait a second! Right now, you're carrying too many items with you. Please come back after putting some of your things into Kafra Storage.^000000")?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
    ctx.lines_as("Dwayne", args!["Wahahahaha~", "I've dug up a fortune!"])?;
    ctx.next()?;
    ctx.lines_as(
        "Dwayne",
        args!["Diamonds! Hundreds and", "thousands of Diamonds,", "all of them mine!", "I'm rich!"],
    )?;
    ctx.call(Function::Emotion, vec![ctx.constant("ET_SMILE")?])?;
    ctx.next()?;
    'b1: {
        let subject1 = Val::from(runtime::select_values(
            ctx,
            &[Val::from("I want to buy some.:Congratulations.")],
        )?);
        let mut matched1 = false;
        let no_case1 = !subject1.loosely_equals(&Val::from(1)) && !subject1.loosely_equals(&Val::from(2));
        if !matched1 && subject1.loosely_equals(&Val::from(1)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as(
                "Dwayne",
                args![
                    "Ah, you have an",
                    "eye for valuables!",
                    "Sure, sure why not!",
                    "I'll give you a discount, too!",
                    "55,000 Zeny for a diamond,",
                    "how does that sound?"
                ],
            )?;
            ctx.next()?;
            ctx.lines_as(
                "Dwayne",
                args![
                    "How many",
                    "diamonds do you need?",
                    "If you change your mind,",
                    "please enter '0' to cancel."
                ],
            )?;
            ctx.next()?;
            let (input, status) = runtime::input_number(ctx, None, None)?;
            l_amount = input;
            if l_amount.clone() == 0 {
                ctx.lines_as("Dwayne", args!["Alright, you've", "canceled the trade.", "Take care!"])?;
                ctx.close_window()?;
                return Err(Stop::End);
            } else {
                if (l_amount.clone().number()? < 1 || l_amount.clone().number()? > 500) {
                    ctx.lines_as("Dwayne", args!["The maximum", "amount is 500.", "Please enter 500 or less."])?;
                    ctx.close_window()?;
                    return Err(Stop::End);
                }
            }
            l_cost = (l_amount.clone().try_mul(Val::from(55000))?);
            l_weight = (l_amount.clone().try_mul(Val::from(100))?);
            if runtime::op(&ctx.var("Zeny").get()?, "<", &l_cost.clone())?.is_true() {
                ctx.lines_as(
                    "Dwayne",
                    args![
                        "Errr...",
                        "I'm sorry, but you",
                        "do not have enough money.",
                        "I'll be losing money if",
                        "I sell them at that price."
                    ],
                )?;
                ctx.close_window()?;
                return Err(Stop::End);
            }
            if runtime::op(
                &(ctx.var("MaxWeight").get()?.try_sub(ctx.var("Weight").get()?)?),
                "<",
                &l_weight.clone(),
            )?
            .is_true()
            {
                ctx.lines_as("Dwayne", args!["Errr...", "You're carrying too many items.", "I don't think give you anything if there's no room in your inventory. Why don't you put some of your stuff into Kafra Storage?"])?;
                ctx.close_window()?;
                return Err(Stop::End);
            }
            ctx.var("Zeny").set((ctx.var("Zeny").get()?.try_sub(l_cost.clone())?))?;
            ctx.call(Function::GetItem, vec![Val::from(732), l_amount.clone()])?;
            ctx.lines_as(
                "Dwayne",
                args!["Thank you for", "buying my diamonds!", "You're welcome to", "come back anytime."],
            )?;
            ctx.close_window()?;
            return Err(Stop::End);
        }
        if !matched1 && subject1.loosely_equals(&Val::from(2)) {
            matched1 = true;
        }
        if matched1 {
            ctx.lines_as(
                "Dwayne",
                args![
                    "Haha, thank you~",
                    "If by any chance",
                    "you need a diamond,",
                    "please drop by.",
                    "I'll sell them to",
                    "you at a cheap price."
                ],
            )?;
            ctx.close_window()?;
            return Err(Stop::End);
        }
    }
    Ok(Val::from(0))
}

pub fn blacksmith_miner(ctx: &Ctx) -> Script {
    blacksmith_miner_body(ctx, Vec::new()).map(|_| ())
}
